ll select TO_DATE(date) AS date, DAYNAME(TRY_TO_DATE(date)) as day, ifnull(\"Walk-ins\"::int,0) as walk_ins, \'Kottayam\' as Store_Location FROM maplemonk.emma_sleep_daily_walk_in_tracker_kottayam; create or replace table maplemonk.emma_sleep_store_conversions as with store_orders as ( select date(order_date) as order_date, case when replace(upper(trim(discount_codes)),\' \',\'\') = \'TVM15\' then \'Trivandrum\' when replace(upper(trim(discount_codes)),\' \',\'\') = \'KOC15\' then \'Kochi\' when replace(upper(trim(discount_codes)),\' \',\'\') = \'CMB15\' or replace(upper(trim(discount_codes)),\' \',\'\') = \'CMB10\' then \'Coimbatore\' when replace(upper(trim(discount_codes)),\' \',\'\') = \'KOZ15\' then \'Kozhikode\' when replace(upper(trim(discount_codes)),\' \',\'\') = \'MDR15\' then \'Madurai\' when replace(upper(trim(discount_codes)),\' \',\'\') = \'TSR15\' or replace(upper(trim(discount_codes)),\' \',\'\') = \'TSR10\'then \'Thrissur\' when replace(upper(trim(discount_codes)),\' \',\'\') = \'BLR15\' then \'Bangalore - Jaya Nagar\' when replace(upper(trim(discount_codes)),\' \',\'\') = \'KOR15\' then \'Bangalore - Kormangala\' when replace(upper(trim(discount_codes)),\' \',\'\') = \'HYD15\' then \'Hyderabad\' when replace(upper(trim(discount_codes)),\' \',\'\') = \'KTM15\' then \'Kottayam\' end as Store_location, sum(r.total_returned_amount) total_returned_amount, sum(r.total_return_quantity) total_return_quantity, sum(r.total_return_orders) return_orders, count(distinct order_id) as total_orders, sum(ifnull(selling_price,0)) as total_sales, sum(ifnull(quantity,0)) as total_sold_quantity, from maplemonk.emmasleep_db_sales_consolidated s left join (select reference_code, split_part(saleorderitemcode,\'_\',1) saleorderitemcode, sum(ifnull(total_credit_note_amount,0)) total_returned_amount, sum(ifnull(returned_quantity,0)) total_return_quantity, count(distinct reference_code) total_return_orders from maplemonk.easyecom_emmasleep_all_returns group by 1,2 ) r on replace(r.reference_code,\'#\',\'\') = replace(s.reference_code,\'#\',\'\') and r.saleorderitemcode = s.saleorderitemcode where replace(upper(trim(discount_codes)),\' \',\'\') in (\'TVM15\',\'KOC15\',\'CMB15\',\'CMB10\',\'KOZ15\',\'MDR15\',\'TSR15\',\'TSR10\',\'BLR15\',\'KOR15\',\'HYD15\',\'KTM15\') group by 1,2 ) select f.date, f.day, f.store_location, f.walk_ins, s.total_orders, s.total_sales, s.total_returned_amount, s.total_return_quantity, s.return_orders from maplemonk.emma_sleep_store_footcount_tracker f left join store_orders s on s.order_date = f.date and lower(s.store_location) = lower(f.store_location) ;",
